const kettle = {
  litres: 2,
  fill() {
    function check() {
      return this === undefined ? "empty" : this.litres;
    }

    return [check(), this.litres];
  },
  later() {
    return function () {
      return this.litres;
    };
  },
};

console.log(kettle.fill().join(","));

try {
  console.log(kettle.later()());
} catch (error) {
  console.log(error.name);
}

console.log((function () { return typeof this; })());
